const SECURE_API='https://dhhwcqczvcbwdwllfcun.supabase.co/functions/v1/multaqa-secure';
let staffToken=localStorage.getItem('multaqa_staff_session')||'',secureEmployee=null,secureDirectory={employees:[],classes:[],buses:[]},activeGrade=5,currentRoster=null,broadcastStream=null,broadcastRecorder=null,broadcastChunks=[],broadcastVideoFile=null,caseUploadFile=null;
const S=id=>document.getElementById(id);
const POSTHOG_KEY='phc_t4Rq2JvPvHE6S2DY4PDcTSnNc9CFrpnrkD7qU72HQWxM';
function phCapture(event,properties={}){try{const distinct=secureEmployee?.employee_id||localStorage.getItem('multaqa_anon_id')||crypto.randomUUID();localStorage.setItem('multaqa_anon_id',distinct);const payload={api_key:POSTHOG_KEY,event,properties:{distinct_id:distinct,app:'multaqa_school',role:secureEmployee?.access_group||'guest',...properties}};if(navigator.sendBeacon)navigator.sendBeacon('https://us.i.posthog.com/capture/',new Blob([JSON.stringify(payload)],{type:'application/json'}));else fetch('https://us.i.posthog.com/capture/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),keepalive:true})}catch{}}
async function staffApi(action,p={}){
 const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),15000);
 try{
  const r=await fetch(SECURE_API,{method:'POST',headers:{'Content-Type':'application/json',...(staffToken?{'x-staff-session':staffToken}:{})},body:JSON.stringify({action,...p}),signal:ctl.signal});
  let d={};try{d=await r.json()}catch{}if(!r.ok||d.ok===false){const x=new Error(d.error||'request_failed');x.code=d.error||'request_failed';throw x}return d
 }catch(e){if(e&&e.name==='AbortError'){const x=new Error('service_timeout');x.code='service_timeout';throw x}throw e}finally{clearTimeout(timer)}
}
function staffError(e){return({invalid_login:'الاسم أو الرمز السري غير صحيح.',pin_not_issued:'لم تصدر الإدارة رمزًا لهذا الاسم بعد.',temporarily_locked:'تم إيقاف المحاولات 15 دقيقة للحماية.',session_required:'انتهت جلسة الدخول. سجلي الدخول من جديد.',weak_pin:'الرمز يجب أن يكون من 6 إلى 12 رقمًا.',forbidden:'ليست لديك صلاحية لهذه العملية.',not_on_duty:'الإبلاغ متاح لمعلمات مناوبة اليوم.',not_found:'لم يتم العثور على السجل.',save_failed:'تعذر حفظ البيانات.',upload_failed:'تعذر رفع الفيديو. حاولي مرة أخرى.',invalid_input:'أكملي الحقول المطلوبة.',service_timeout:'خدمة الدخول لا تستجيب الآن بسبب عطل مؤقت في قاعدة البيانات. حاولي بعد دقيقة.'}[e?.code]||'تعذر إتمام العملية الآن.')}
function secureAdmin(){return secureEmployee&&['admin','management'].includes(secureEmployee.access_group)}
function caseAccess(){return secureEmployee&&['admin','management','social'].includes(secureEmployee.access_group)}
function setSecureEmployee(e){
 secureEmployee=e;employee=e;localStorage.removeItem('multaqa_employee');
 const g=S('identityGreeting');if(g){g.textContent='مرحبًا '+(e.profile?.welcome_name||e.short_name);g.style.display='inline-flex'}
 document.querySelectorAll('[data-admin-only]').forEach(x=>x.style.display=secureAdmin()?'':'none');
 if(S('staffWelcome'))S('staffWelcome').textContent=e.welcome_message||('مرحبًا '+e.short_name);
 if(S('staffName'))S('staffName').textContent=e.profile?.welcome_name||e.short_name;
 if(S('staffRole'))S('staffRole').textContent=[e.profile?.display_title||e.role,e.profile?.subject].filter(Boolean).join(' • ');
 const img=S('staffPhoto');if(img){img.innerHTML=e.profile?.photo_url?'<img src="'+esc(e.profile.photo_url)+'" alt="">':'<span>'+(e.kind==='teacher'?'👩‍🏫':'🏛️')+'</span>'}
}
function prepareSecureLogin(){
 const box=S('modal')?.querySelector('.modal-box');if(!box)return;
 const sub=box.querySelector('.sub');if(sub)sub.textContent='دخول آمن: الاسم الأول والقبيلة + الرمز السري الشخصي';
 const form=S('identityForm');if(form&&!S('identityPin'))form.innerHTML='<label>الاسم الأول + القبيلة</label><input id="identityName" list="identitySuggestions" required autocomplete="username" placeholder="مثال: ثرياء الناعبية"><datalist id="identitySuggestions"></datalist><label>الرمز السري الشخصي</label><input id="identityPin" type="password" inputmode="numeric" minlength="6" maxlength="12" required autocomplete="current-password" placeholder="••••••"><div id="identityError" role="alert" style="display:none;margin-top:8px;color:#9b1c31;font-size:12px;font-weight:800"></div><button id="identitySubmit" type="submit" class="btn btn-solid">دخول إلى ملفي</button>';
 const sw=box.querySelector('.switch');if(sw)sw.textContent='الرمز شخصي ولا يظهر لأي مستخدمة أخرى. بعد أول دخول سيطلب النظام تغييره.';
}
window.openIdentity=()=>{prepareSecureLogin();openById('modal');setTimeout(()=>S('identityName')?.focus(),50)};
window.identifyEmployee=async ev=>{
 ev?.preventDefault();prepareSecureLogin();const nameEl=S('identityName'),pinEl=S('identityPin'),box=S('identityError'),btn=S('identitySubmit');
 if(!nameEl||!pinEl||!box){toast('تعذر تجهيز نموذج الدخول. حدّثي الصفحة مرة واحدة.');return false}
 const name=nameEl.value.trim(),pin=pinEl.value.trim();box.style.display='none';if(btn){btn.disabled=true;btn.textContent='جاري الدخول…'}
 try{const d=await staffApi('login',{name,pin});staffToken=d.token;localStorage.setItem('multaqa_staff_session',staffToken);setSecureEmployee(d.employee);closeModal();toast('✅ '+d.employee.welcome_message);if(d.must_change_pin)setTimeout(()=>changeMyPin(true),350);setTimeout(()=>openStaffCenter(),250);return false}catch(e){box.textContent=staffError(e);box.style.display='block';return false}finally{if(btn){btn.disabled=false;btn.textContent='دخول إلى ملفي'}}
};
window.changeMyPin=async forced=>{
 const pin=prompt(forced?'هذا رمز مؤقت. اكتبي رمزك الجديد من 6 إلى 12 رقمًا:':'اكتبي الرمز السري الجديد من 6 إلى 12 رقمًا:');if(!pin)return;
 try{await staffApi('change_pin',{pin});toast('✅ تم تغيير الرمز السري')}catch(e){toast(staffError(e));if(forced)setTimeout(()=>changeMyPin(true),300)}
};
window.staffLogout=async()=>{try{await staffApi('logout')}catch{}staffToken='';secureEmployee=null;employee=null;localStorage.removeItem('multaqa_staff_session');const g=S('identityGreeting');if(g)g.style.display='none';closeById('staffCenterModal');toast('تم تسجيل الخروج')};
async function restoreStaff(){
 localStorage.removeItem('multaqa_employee');employee=null;
 if(!staffToken)return;
 try{const d=await staffApi('me');setSecureEmployee(d.employee)}catch{staffToken='';localStorage.removeItem('multaqa_staff_session')}
}
function injectStaffCenter(){
 if(S('staffCenterModal'))return;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal staff-center" id="staffCenterModal"><div class="modal-box">
 <button class="close" onclick="closeById('staffCenterModal')">✕</button>
 <header class="staff-profile"><div class="staff-photo" id="staffPhoto"><span>👩‍🏫</span></div><div><small id="staffWelcome">أهلًا بكِ</small><h3 id="staffName">ملفي المدرسي</h3><p id="staffRole"></p></div><div class="staff-account"><button onclick="changeMyPin(false)">تغيير الرمز</button><button onclick="staffLogout()">خروج</button></div></header>
 <div class="staff-admin-bar" data-admin-only><button type="button" onclick="staffTab('home')">🏠 العودة إلى لوحة الإدارة الرئيسية</button><span>مديرة النظام • جميع الصلاحيات مفعّلة</span></div>
 <div class="staff-tabs">
  <button data-staff-tab="home" onclick="staffTab('home')">🏠 الرئيسية</button><button data-staff-tab="schedule" onclick="staffTab('schedule')">📚 جدولي</button><button data-staff-tab="attendance" onclick="staffTab('attendance')">✅ الطالبات</button>
  <button data-staff-tab="permissions" onclick="staffTab('permissions')">🚪 الاستئذان</button><button data-staff-tab="duty" onclick="staffTab('duty')">🦺 المناوبة</button><button data-staff-tab="broadcast" onclick="staffTab('broadcast')">📻 الإذاعة</button>
  <button data-staff-tab="staff" data-admin-only onclick="staffTab('staff')">👩‍🏫 المعلمات</button><button data-staff-tab="coverage" onclick="staffTab('coverage')">🔄 الاحتياط</button>
  <button data-staff-tab="excellence" data-admin-only onclick="staffTab('excellence')">🏆 التميز</button><button data-staff-tab="cases" onclick="staffTab('cases')">🧩 الحالات</button>
  <button data-staff-tab="activities" onclick="staffTab('activities')">🎯 الأنشطة</button><button data-staff-tab="gifted" onclick="staffTab('gifted')">🌟 الموهوبات</button><button data-staff-tab="social" onclick="staffTab('social')">🤝 الأخصائية</button>
  <button data-staff-tab="buses" onclick="staffTab('buses')">🚌 الحافلات</button><button data-staff-tab="analytics" data-admin-only onclick="staffTab('analytics')">📊 المؤشرات</button>
  <button data-staff-tab="security" data-admin-only onclick="staffTab('security')">🔐 الرموز</button>
 </div><main id="staffPane" class="staff-pane"></main></div></div>`);
 const strip=S('portalStrip');if(strip&&!S('staffCenterEntry'))strip.insertAdjacentHTML('afterbegin','<button class="portal-entry featured" id="staffCenterEntry" onclick="openStaffCenter()"><em>📊</em><b>مركز التشغيل والتحليل</b><small>الحضور • الاستئذان • المناوبة • الاحتياط • المؤشرات</small></button>');
 else S('modules')?.insertAdjacentHTML('beforebegin','<section class="portal-strip"><button class="portal-entry featured" id="staffCenterEntry" onclick="openStaffCenter()"><em>📊</em><b>مركز التشغيل والتحليل</b><small>كل وحدات المدرسة في مكان واحد</small></button></section>');
}
function updateSecureLabels(){
 document.querySelectorAll('a,button,b,h1,h2,h3,h4').forEach(x=>{
  const t=x.textContent.trim();
  if(t==='تحديد الاسم')x.textContent='دخول الموظفات';
  if(t==='عرّفي النظام باسمك')x.textContent='دخول الموظفات بالاسم والرمز';
  if(t==='دخول الموظفات بالاسم')x.textContent='دخول آمن بالاسم والرمز';
  if(t==='اكتبي اسمك')x.textContent='سجلي دخولك';
 });
}
window.openStaffCenter=async()=>{
 if(!staffToken||!secureEmployee){toast('سجلي الدخول بالاسم والرمز السري');return openIdentity()}
 openById('staffCenterModal');if(!secureDirectory.classes.length)try{secureDirectory=await staffApi('directory')}catch(e){toast(staffError(e))}
 setSecureEmployee(secureEmployee);staffTab('home')
};
window.staffTab=async tab=>{
 if(tab!=='broadcast')stopBroadcastCamera(true);
 document.querySelectorAll('[data-staff-tab]').forEach(x=>x.classList.toggle('active',x.dataset.staffTab===tab));const pane=S('staffPane');pane.innerHTML='<div class="staff-loading">جاري تحميل الوحدة…</div>';
 phCapture('school_module_opened',{module:tab});try{if(tab==='home')await renderHome();if(tab==='schedule')await renderSecureSchedule();if(tab==='attendance')renderGrades();if(tab==='permissions')await renderPermissions();if(tab==='duty')await renderSecureDuty();if(tab==='broadcast')await renderBroadcasts();if(tab==='staff')renderStaffAdmin();if(tab==='coverage')await renderCoverage();if(tab==='excellence')renderExcellence();if(tab==='cases')renderCases();if(tab==='activities')await renderActivities();if(tab==='gifted')await renderGifted();if(tab==='social')renderSocialWorker();if(tab==='buses')renderBuses();if(tab==='analytics')await renderAnalytics();if(tab==='security')renderSecurity()}catch(e){pane.innerHTML='<div class="staff-empty">'+staffError(e)+'</div>'}
};
async function renderSecureSchedule(){
 const chosen=secureAdmin()?S('adminScheduleTeacher')?.value||'':'' ,d=await staffApi('teacher_schedule',chosen?{employee_name:chosen}:{}),row=d.schedule||{},schedule=row.schedule||{},days=['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس'];
 const picker=secureAdmin()?'<label class="schedule-picker">عرض جدول معلمة<select id="adminScheduleTeacher" onchange="renderSecureSchedule()"><option value="">جدولي</option>'+secureDirectory.employees.filter(x=>x.kind==='teacher').map(x=>'<option '+(chosen===x.full_name?'selected':'')+'>'+esc(x.full_name)+'</option>').join('')+'</select></label>':'';
 S('staffPane').innerHTML='<div class="today-title"><div><small>الجدول الأسبوعي الرسمي'+(row.page?' • صفحة '+row.page:'')+'</small><h2>📚 جدول '+esc(d.employee.short_name||d.employee.full_name)+'</h2></div>'+picker+'</div><div class="secure-schedule-grid">'+days.map(day=>'<section class="staff-card secure-day-card"><h3>'+day+'</h3><div class="secure-periods">'+[0,1,2,3,4,5,6].map(i=>'<div class="secure-period '+((schedule[day]||[])[i]?'has-class':'free-period')+'"><b>الحصة '+(i+1)+'</b><span>'+esc((schedule[day]||[])[i]||'فراغ')+'</span></div>').join('')+'</div></section>').join('')+'</div>';
}
async function renderHome(){
 const d=await staffApi('dashboard'),p=S('staffPane');p.innerHTML=`<div class="today-title"><div><small>لوحة اليوم</small><h2>${new Intl.DateTimeFormat('ar-OM',{weekday:'long',day:'numeric',month:'long'}).format(new Date())}</h2></div><button class="staff-primary" onclick="staffTab('analytics')" data-admin-only>عرض المؤشرات</button></div>
 <div class="kpi-grid"><div><em>👧</em><small>حاضرات</small><b>${d.students.present}</b></div><div><em>❌</em><small>غائبات</small><b>${d.students.absent}</b></div><div><em>⏰</em><small>متأخرات</small><b>${d.students.late}</b></div><div><em>👩‍🏫</em><small>معلمات حاضرات</small><b>${d.teachers.present}</b></div><div><em>🚪</em><small>طلبات استئذان</small><b>${d.permissions.pending}</b></div><div><em>⚠️</em><small>حصص تحتاج تغطية</small><b>${d.coverage.needed}</b></div><div><em>🦺</em><small>مناوبات مؤكدة</small><b>${d.duty.confirmed}</b></div><div><em>🏫</em><small>صفوف بلا معلمة</small><b>${d.observations.no_teacher}</b></div></div>
 <h3 class="staff-section-title">الصفوف من الأول إلى السادس</h3><div class="grade-grid">${[1,2,3,4,5,6].map(g=>`<button onclick="openGrade(${g})"><span>الصف</span><b>${['','الأول','الثاني','الثالث','الرابع','الخامس','السادس'][g]}</b><small>${secureDirectory.classes.filter(c=>gradeOf(c)===g).length} فصول</small></button>`).join('')}</div><div id="gradeClasses"></div>`;
 document.querySelectorAll('[data-admin-only]').forEach(x=>x.style.display=secureAdmin()?'':'none')
}
function gradeOf(c){const m=String(c).match(/([1-6])\s*[\/\\]/);if(m)return +m[1];return ['الأول','الثاني','الثالث','الرابع','الخامس','السادس'].findIndex(x=>String(c).includes(x))}
window.openGrade=g=>{activeGrade=g;const a=secureDirectory.classes.filter(c=>gradeOf(c)===g);S('gradeClasses').innerHTML='<h3 class="staff-section-title">فصول الصف '+['','الأول','الثاني','الثالث','الرابع','الخامس','السادس'][g]+'</h3><div class="class-grid">'+a.map(c=>'<button onclick="openClassAttendance(\''+esc(c)+'\')"><b>'+esc(c)+'</b><small>الكشف والجدول والحضور</small></button>').join('')+'</div>'};
function renderGrades(){S('staffPane').innerHTML='<h2>حضور وغياب الطالبات</h2><p class="staff-help">اختاري الصف ثم الفصل. يُحفظ التسجيل بالتاريخ والحصة والمعلمة.</p><div class="grade-grid">'+[1,2,3,4,5,6].map(g=>'<button onclick="showGradeForAttendance('+g+')"><span>الصف</span><b>'+['','الأول','الثاني','الثالث','الرابع','الخامس','السادس'][g]+'</b></button>').join('')+'</div><div id="attendanceClasses"></div>'}
window.showGradeForAttendance=g=>{S('attendanceClasses').innerHTML='<div class="class-grid">'+secureDirectory.classes.filter(c=>gradeOf(c)===g).map(c=>'<button onclick="openClassAttendance(\''+esc(c)+'\')"><b>'+esc(c)+'</b></button>').join('')+'</div>'};
window.openClassAttendance=async cls=>{
 staffTab('attendance');setTimeout(async()=>{const p=S('staffPane');p.innerHTML='<div class="staff-loading">تحميل كشف '+esc(cls)+'…</div>';const period=Math.max(0,Math.min(7,+(prompt('رقم الحصة من 1 إلى 7، أو 0 للحضور اليومي:','1')||1)));const d=await staffApi('class_roster',{class_name:cls,period});currentRoster={class_name:cls,period,students:d.students,date:new Date().toISOString().slice(0,10)};const old=new Map((d.attendance||[]).map(x=>[x.student_school_id,x]));p.innerHTML='<div class="today-title"><div><small>الحصة '+period+'</small><h2>'+esc(cls)+'</h2><p>'+d.students.length+' طالبة</p></div><button class="staff-primary" onclick="saveRoster()">حفظ الكشف</button></div><div class="roster-tools"><button onclick="markAllPresent()">تحديد الكل حاضر</button></div><div class="roster">'+d.students.map((s,i)=>{const x=old.get(s.school_id)||{status:'present'};return '<div class="roster-row" data-sid="'+esc(s.school_id)+'"><span class="serial">'+(i+1)+'</span><b>'+esc(s.name)+'</b><select class="att-status"><option value="present" '+(x.status==='present'?'selected':'')+'>✅ حاضر</option><option value="absent" '+(x.status==='absent'?'selected':'')+'>❌ غائب</option><option value="late" '+(x.status==='late'?'selected':'')+'>⏰ متأخر</option><option value="excused" '+(x.status==='excused'?'selected':'')+'>📝 بعذر</option><option value="permission" '+(x.status==='permission'?'selected':'')+'>🚪 استئذان</option></select><input class="att-note" placeholder="السبب أو الملاحظة" value="'+esc(x.reason||x.note||'')+'"></div>'}).join('')+'</div>'},50)
};
window.markAllPresent=()=>document.querySelectorAll('.att-status').forEach(x=>x.value='present');
window.saveRoster=async()=>{if(!currentRoster)return;const items=[...document.querySelectorAll('.roster-row')].map(r=>({student_school_id:r.dataset.sid,status:r.querySelector('.att-status').value,reason:r.querySelector('.att-note').value}));try{const d=await staffApi('save_student_attendance',{class_name:currentRoster.class_name,period:currentRoster.period,date:currentRoster.date,items});toast('✅ تم حفظ '+d.saved+' طالبة')}catch(e){toast(staffError(e))}};
async function renderPermissions(){
 const d=await staffApi('permissions');S('staffPane').innerHTML=`<div class="two-col"><section class="staff-card"><h3>🚪 طلب استئذان</h3><label>النوع</label><select id="permType"><option value="returning">استئذان والعودة</option><option value="end_of_day">حتى نهاية الدوام</option><option value="periods">خروج لحصة أو أكثر</option></select><div class="form-row"><div><label>من الحصة</label><select id="permFrom">${[1,2,3,4,5,6,7].map(x=>'<option>'+x+'</option>').join('')}</select></div><div><label>إلى الحصة</label><select id="permTo">${[1,2,3,4,5,6,7].map(x=>'<option>'+x+'</option>').join('')}</select></div></div><div class="form-row"><div><label>وقت الخروج</label><input id="permLeave" type="time"></div><div><label>العودة المتوقعة</label><input id="permReturn" type="time"></div></div><label>تصنيف السبب</label><select id="permReasonCat">${reasonOptions()}</select><label>السبب</label><textarea id="permReason"></textarea><label>ملاحظة</label><textarea id="permNote"></textarea><button class="staff-primary" onclick="submitPermission()">إرسال للإدارة</button></section><section class="staff-card"><h3>الطلبات</h3><div class="request-list">${(d.items||[]).map(permissionCard).join('')||'<div class="staff-empty">لا توجد طلبات</div>'}</div></section></div>`
}
function reasonOptions(){return '<option value="health">صحي</option><option value="medical_appointment">موعد طبي</option><option value="family">ظرف أسري</option><option value="child">طفل</option><option value="government">مراجعة جهة حكومية</option><option value="emergency">طارئ</option><option value="official_task">مهمة رسمية</option><option value="transport">مواصلات</option><option value="other">أخرى</option>'}
function permissionCard(x){const labels={pending:'🟡 بانتظار الموافقة',approved:'🟢 موافق',rejected:'🔴 مرفوض',returned:'🔵 عادت للمدرسة'};return '<article><b>'+labels[x.status]+'</b><small>الحصص '+(x.from_period||'—')+' إلى '+(x.to_period||'—')+'</small><p>'+esc(x.reason)+'</p>'+(secureAdmin()&&x.status==='pending'?'<div><button onclick="decidePermission(\''+x.id+'\',\'approved\')">موافقة</button><button onclick="decidePermission(\''+x.id+'\',\'rejected\')">رفض</button></div>':'')+'</article>'}
window.submitPermission=async()=>{try{await staffApi('request_permission',{permission_type:S('permType').value,from_period:+S('permFrom').value,to_period:+S('permTo').value,leave_time:S('permLeave').value,expected_return_time:S('permReturn').value,reason_category:S('permReasonCat').value,reason:S('permReason').value,note:S('permNote').value});toast('✅ تم إرسال الطلب');renderPermissions()}catch(e){toast(staffError(e))}};
window.decidePermission=async(id,status)=>{try{const d=await staffApi('decide_permission',{id,status});toast(status==='approved'?'✅ تمت الموافقة وتوزيع الاحتياط':'تم رفض الطلب');renderPermissions()}catch(e){toast(staffError(e))}};
