async function renderSecureDuty(){
 const [d,w]=await Promise.all([staffApi('duty_today'),staffApi('duty_week')]);
 const slotNames={morning:'الطابور الصباحي',shade:'المظلة',coop:'التعاونية',between:'بين الفصول',cars:'السيارات',buses:'الحافلات',reserve:'احتياط'};
 const week='<div class="today-title"><div><small>خطة المناوبات الكاملة</small><h2>🦺 المناوبات من الأحد إلى الخميس</h2></div></div><div class="duty-week-grid">'+(w.days||[]).map(day=>'<section class="staff-card duty-week-card"><h3>'+esc(day.day_name)+'</h3><p><b>المشرفات:</b> '+esc((day.admins||[]).join('، ')||'—')+'</p><div class="duty-slot-list">'+Object.entries(day.slots||{}).map(([key,names])=>'<div><b>'+esc(slotNames[key]||key)+'</b><span>'+esc((names||[]).join('، ')||'—')+'</span></div>').join('')+'</div></section>').join('')+'</div>';
 S('staffPane').innerHTML=week+'<div class="today-title duty-today-title"><div><small>مناوبة '+esc(d.day)+'</small><h2>متابعة حضور اليوم والجولات</h2></div></div><div class="duty-secure-grid">'+d.members.map(m=>{const c=d.checks.find(x=>x.employee_id===m.employee_id);return '<article><b>'+esc(m.short_name)+'</b><small>'+(c?({present:'✅ حاضرة',absent:'❌ غائبة',late:'⏰ متأخرة',excused:'📝 بعذر'}[c.status]):'⏳ لم تؤكد')+'</small>'+(d.is_supervisor?'<div><select id="ds-'+m.employee_id+'"><option value="present">حاضرة</option><option value="absent">غائبة</option><option value="late">متأخرة</option><option value="excused">بعذر</option></select><select id="star-'+m.employee_id+'"><option value="0">بدون نجوم</option><option value="1">⭐</option><option value="2">⭐⭐</option><option value="3">⭐⭐⭐</option><option value="4">⭐⭐⭐⭐</option><option value="5">⭐⭐⭐⭐⭐</option></select><button onclick="confirmDuty(\''+esc(m.short_name)+'\',\''+m.employee_id+'\')">تأكيد</button></div>':'')+'</article>'}).join('')+'</div><section class="staff-card report-class"><h3>بلاغ معلمة المناوبة بين الفصول</h3><div class="form-row"><select id="reportClass">'+secureDirectory.classes.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><select id="reportStatus"><option value="organized">🟢 صف منظم</option><option value="no_teacher">🚨 صف بدون معلمة</option><option value="problem">⚠️ صف به مشكلة</option></select><select id="reportPeriod">'+[1,2,3,4,5,6,7].map(x=>'<option value="'+x+'">الحصة '+x+'</option>').join('')+'</select></div><textarea id="reportNote" placeholder="تفاصيل البلاغ"></textarea><button class="staff-primary" onclick="reportClassStatus()">إرسال البلاغ</button></section>'
}
window.confirmDuty=async(name,id)=>{try{await staffApi('confirm_duty',{employee_name:name,status:S('ds-'+id).value,stars:+S('star-'+id).value});toast('✅ تم تأكيد المناوبة');renderSecureDuty()}catch(e){toast(staffError(e))}};
