function renderExcellence(){S('staffPane').innerHTML='<div class="two-col"><section class="staff-card"><h2>👑 تاج تميز المعلمات</h2><select id="exTeacher">'+employeeOptions()+'</select>'+checks(teacherReasons,'tr')+'<textarea id="trNote" placeholder="ملاحظة إضافية"></textarea><button class="staff-primary" onclick="saveTeacherExcellence()">منح تاج التميز</button></section><section class="staff-card"><h2>🏆 كأس تميز الصفوف</h2><select id="exClass">'+secureDirectory.classes.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select>'+checks(classReasons,'cr')+'<textarea id="crNote" placeholder="ملاحظة إضافية"></textarea><button class="staff-primary" onclick="saveClassExcellence()">منح كأس التميز</button></section></div>'}
