window.saveClassExcellence=async()=>{try{await staffApi('save_excellence',{type:'class',class_label:S('exClass').value,reasons:selected('cr'),note:S('crNote').value});toast('🏆 تم منح كأس التميز')}catch(e){toast(staffError(e))}};
const activityNames={broadcast:'الإذاعة',scouts_guides:'الكشافة والمرشدات',safety:'الأمن والسلامة',mothers_council:'مجلس الأمهات',school_health:'الصحة المدرسية'};
function employeeChecks(id,selected=[]){return '<div class="multi-people" id="'+id+'">'+secureDirectory.employees.filter(x=>x.kind==='teacher').map(x=>'<label><input type="checkbox" value="'+esc(x.employee_id)+'" '+(selected.includes(x.employee_id)?'checked':'')+'><span>'+esc(x.short_name||x.full_name)+'</span></label>').join('')+'</div>'}
