async function renderActivities(){
 const d=await staffApi('activities'),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Muscat'}).format(new Date());S('staffPane').innerHTML='<div class="today-title"><div><small>المسؤولات والأعضاء والإنجازات والمهام</small><h2>🎯 الأنشطة المدرسية</h2></div></div>'+(secureAdmin()?'<section class="staff-card activity-editor"><h3>إضافة نشاط</h3><div class="form-row"><label>نوع النشاط<select id="activityType">'+Object.entries(activityNames).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label><label>التاريخ<input id="activityDate" type="date" value="'+today+'"></label></div><label>عنوان النشاط<input id="activityTitle" placeholder="عنوان النشاط"></label><label>الوصف<textarea id="activityDescription" placeholder="تفاصيل النشاط وخطته"></textarea></label><label>المعلمات المسؤولات — يمكن اختيار أكثر من معلمة</label>'+employeeChecks('activityResponsibles')+'<label>الأعضاء والطالبات المشاركات<textarea id="activityMembers" placeholder="كل اسم في سطر"></textarea></label><button class="staff-primary" onclick="saveActivity()">حفظ النشاط</button></section>':'')+'<div class="activity-list">'+((d.items||[]).map(activityCard).join('')||'<div class="staff-empty">لا توجد أنشطة مسجلة بعد.</div>')+'</div>';
}
function activityCard(a){const tasks=(a.tasks||[]).map(t=>'<li><b>'+esc(t.title)+'</b><span>'+esc((t.assignee_names||[]).join('، ')||'غير مسندة')+'</span><button onclick="completeActivityTask('+t.id+')">'+(t.status==='completed'?'مكتملة ✓':'إتمام المهمة')+'</button></li>').join(''),ach=(a.achievements||[]).map(x=>'<li>🏅 '+esc(x.title)+'</li>').join('');return '<article class="staff-card activity-card"><header><div><small>'+esc(a.activity_date)+'</small><h3>'+esc(a.title)+'</h3></div><span>'+esc(activityNames[a.activity_type]||a.activity_type)+'</span></header><p>'+esc(a.description||'')+'</p><p><b>المسؤولات:</b> '+esc((a.responsibles||[]).map(x=>x.name).join('، ')||'لم تحدد')+'</p><p><b>الأعضاء:</b> '+esc((a.members||[]).join('، ')||'لم يسجلوا')+'</p><h4>مهام الإدارة</h4><ul class="activity-items">'+(tasks||'<li>لا توجد مهام</li>')+'</ul><h4>الإنجازات</h4><ul class="activity-items">'+(ach||'<li>لا توجد إنجازات</li>')+'</ul><div class="activity-actions"><button onclick="showActivityTaskForm(\''+a.id+'\')">➕ مهمة</button><button onclick="showAchievementForm(\''+a.id+'\')">🏅 إنجاز</button></div><div id="activityExtra-'+a.id+'"></div></article>'}
