window.completeActivityTask=async id=>{try{await staffApi('complete_activity_task',{id,status:'completed'});phCapture('activity_task_completed');toast('✅ اكتملت المهمة');renderActivities()}catch(e){toast(staffError(e))}};
window.showAchievementForm=id=>{S('activityExtra-'+id).innerHTML='<div class="inline-editor"><input id="achievementTitle-'+id+'" placeholder="عنوان الإنجاز"><textarea id="achievementDetails-'+id+'" placeholder="تفاصيل الإنجاز"></textarea><button class="staff-primary" onclick="saveAchievement(\''+id+'\')">حفظ الإنجاز</button></div>'};
window.saveAchievement=async id=>{try{await staffApi('save_activity_achievement',{activity_id:id,title:S('achievementTitle-'+id).value,details:S('achievementDetails-'+id).value});phCapture('activity_achievement_saved');toast('🏅 تم حفظ الإنجاز');renderActivities()}catch(e){toast(staffError(e))}};
async function renderGifted(){const d=await staffApi('gifted_students');S('staffPane').innerHTML='<div class="today-title"><div><small>المواهب والمشاركات وخطط الدعم</small><h2>🌟 الطالبات الموهوبات</h2></div><div class="supervisor-note">المشرف الإداري: <b>بانتظار الاسم ورقم الدخول</b></div></div>'+(caseAccess()?'<section class="staff-card gifted-editor"><h3>إضافة أو تحديث طالبة موهوبة</h3><div class="form-row"><label>رقم الطالبة<input id="giftedStudentId" placeholder="الرقم المدرسي"></label><label>الموهبة<input id="giftedCategory" placeholder="مثال: الإلقاء أو الرسم"></label></div><label>وصف الموهبة<textarea id="giftedDescription"></textarea></label><label>خطة الدعم<textarea id="giftedPlan"></textarea></label><button class="staff-primary" onclick="saveGifted()">حفظ الطالبة</button></section>':'')+'<div class="gifted-grid">'+((d.items||[]).map(giftedCard).join('')||'<div class="staff-empty">لم تُسجل طالبات موهوبات بعد.</div>')+'</div>'}
function giftedCard(x){const s=x.student||{};return '<article class="staff-card gifted-card"><div><small>'+esc(s.class_name||'')+' • '+esc(s.school_id||x.student_school_id)+'</small><h3>'+esc(s.name||x.student_school_id)+'</h3><b>🌟 '+esc(x.talent_category)+'</b><p>'+esc(x.talent_description||'')+'</p><p><b>خطة الدعم:</b> '+esc(x.support_plan||'لم توضع بعد')+'</p></div><h4>المشاركات</h4><ul>'+((x.participations||[]).map(p=>'<li>'+esc(p.participation_date)+' — '+esc(p.title)+(p.result?' • '+esc(p.result):'')+'</li>').join('')||'<li>لا توجد مشاركات</li>')+'</ul>'+(caseAccess()?'<button onclick="showGiftedParticipation(\''+x.student_school_id+'\')">➕ إضافة مشاركة</button><div id="giftedExtra-'+x.student_school_id+'"></div>':'')+'</article>'}
window.saveGifted=async()=>{try{await staffApi('save_gifted_student',{student_school_id:S('giftedStudentId').value,talent_category:S('giftedCategory').value,talent_description:S('giftedDescription').value,support_plan:S('giftedPlan').value,status:'active'});phCapture('gifted_student_saved');toast('🌟 تم حفظ ملف الموهبة');renderGifted()}catch(e){toast(staffError(e))}};
window.showGiftedParticipation=sid=>{S('giftedExtra-'+sid).innerHTML='<div class="inline-editor"><input id="partTitle-'+sid+'" placeholder="اسم المشاركة"><input id="partResult-'+sid+'" placeholder="النتيجة أو الإنجاز"><button class="staff-primary" onclick="saveGiftedParticipation(\''+sid+'\')">حفظ المشاركة</button></div>'};
window.saveGiftedParticipation=async sid=>{try{await staffApi('save_gifted_participation',{student_school_id:sid,title:S('partTitle-'+sid).value,result:S('partResult-'+sid).value});phCapture('gifted_participation_saved');toast('✅ تم حفظ المشاركة');renderGifted()}catch(e){toast(staffError(e))}};
function renderSocialWorker(){if(!caseAccess())return S('staffPane').innerHTML='<div class="staff-empty">هذا القسم خاص بالإدارة والأخصائية الاجتماعية.</div>';S('staffPane').innerHTML='<div class="today-title"><div><small>ملفات سرية • خطط • متابعة • مرفقات</small><h2>🤝 قسم الأخصائية الاجتماعية</h2></div></div><div class="case-search"><select id="caseClass"><option value="">كل الصفوف</option>'+secureDirectory.classes.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><input id="caseQuery" placeholder="اسم الطالبة"><button class="staff-primary" onclick="searchStudentCases()">بحث</button></div><div id="caseResults"></div><div id="caseDetail"></div>'}
function renderCases(){S('staffPane').innerHTML='<h2>🧩 متابعة حالات الطالبات</h2><p class="staff-help">المعلومات الصحية والاجتماعية تظهر فقط للإدارة وفريق الحالات، بينما تستطيع المعلمة إضافة ملاحظتها الدراسية.</p><div class="case-search"><select id="caseClass"><option value="">كل الصفوف</option>'+secureDirectory.classes.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><input id="caseQuery" placeholder="اسم الطالبة"><button class="staff-primary" onclick="searchStudentCases()">بحث</button></div><div id="caseResults"></div><div id="caseDetail"></div>'}
window.searchStudentCases=async()=>{try{const d=await staffApi('search_students',{class_name:S('caseClass').value,query:S('caseQuery').value});S('caseResults').innerHTML='<div class="case-result-grid">'+d.students.map(s=>'<button onclick="openStudentCase(\''+s.school_id+'\')"><b>'+esc(s.name)+'</b><small>'+esc(s.class_name)+'</small></button>').join('')+'</div>'}catch(e){toast(staffError(e))}};
window.openStudentCase=async sid=>{try{
 const d=await staffApi('student_case',{student_school_id:sid}),c=d.case||{},s=d.student,secure=caseAccess();caseUploadFile=null;
 const fields=secure?'<div class="case-fields"><label>مكان السكن<input id="cResidence" value="'+esc(c.residence||s.area||'')+'"></label><label>رقم الهاتف<input id="cPhone" value="'+esc(c.contact_phone||s.guardian_phone||'')+'"></label><label>الحالة الاجتماعية<textarea id="cSocial">'+esc(c.social_status||'')+'</textarea></label><label>مستوى المعيشة<select id="cLiving"><option value="">غير محدد</option>'+['ممتاز','جيد','متوسط','محدود','يحتاج دعم'].map(x=>'<option '+(c.living_standard===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>وضع الأسرة<textarea id="cFamily">'+esc(c.family_status||'')+'</textarea></label><label>الحالة الصحية<textarea id="cHealth">'+esc(c.health_status||'')+'</textarea></label><label>مشكلات نفسية<textarea id="cPsych">'+esc(c.psychological_notes||'')+'</textarea></label><label>مشكلات إدراكية أو تعلمية<textarea id="cCognitive">'+esc(c.cognitive_notes||'')+'</textarea></label><label>ملاحظات إدارية<textarea id="cAdminNotes">'+esc(c.administrative_notes||'')+'</textarea></label><label>الاحتياجات والدعم المطلوب<textarea id="cSupport">'+esc(c.support_needs||'')+'</textarea></label><label>المشكلة التي تحتاج متابعة<textarea id="cIssue">'+esc(c.follow_up_issue||'')+'</textarea></label><label>المستوى الدراسي<select id="cLevel"><option value="">غير محدد</option><option value="advanced" '+(c.academic_level==='advanced'?'selected':'')+'>متقدم</option><option value="average" '+(c.academic_level==='average'?'selected':'')+'>متوسط</option><option value="support" '+(c.academic_level==='support'?'selected':'')+'>يحتاج دعم</option></select></label><label>حالة المتابعة<select id="cFollowStatus"><option value="open">مفتوحة</option><option value="monitoring" '+(c.follow_up_status==='monitoring'?'selected':'')+'>قيد المتابعة</option><option value="stable" '+(c.follow_up_status==='stable'?'selected':'')+'>مستقرة</option><option value="closed" '+(c.follow_up_status==='closed'?'selected':'')+'>مغلقة</option></select></label><label>موعد المتابعة القادمة<input id="cNextDate" type="date" value="'+esc(c.next_follow_up_date||'')+'"></label></div><button class="staff-primary" onclick="saveStudentCase(\''+sid+'\')">حفظ ملف الطالبة</button>':'';
 const followups=secure?'<section class="case-section"><h3>سجل المتابعة</h3><div class="case-notes">'+((d.followups||[]).map(x=>'<article><b>'+esc(x.follow_up_date)+' • '+esc(x.follow_up_type)+'</b><p>'+esc(x.summary)+'</p><small>'+esc(x.outcome||'')+'</small></article>').join('')||'<p>لا توجد متابعة مسجلة.</p>')+'</div><div class="inline-editor"><input id="followType" placeholder="نوع المتابعة: مقابلة أو اتصال"><textarea id="followSummary" placeholder="ملخص المتابعة"></textarea><textarea id="followOutcome" placeholder="النتيجة والخطوة القادمة"></textarea><button onclick="addCaseFollowup(\''+sid+'\')">حفظ المتابعة</button></div></section>':'';
 const plans=secure?'<section class="case-section"><h3>خطة الحالة</h3><div class="case-notes">'+((d.plans||[]).map(x=>'<article><b>'+esc(x.title)+'</b><p><strong>الأهداف:</strong> '+esc(x.goals)+'</p><p><strong>الإجراءات:</strong> '+esc(x.actions)+'</p></article>').join('')||'<p>لا توجد خطة بعد.</p>')+'</div><div class="inline-editor"><input id="planTitle" placeholder="عنوان الخطة"><textarea id="planGoals" placeholder="أهداف الخطة"></textarea><textarea id="planActions" placeholder="الإجراءات والتنفيذ"></textarea><input id="planResponsible" placeholder="الجهات المسؤولة"><button onclick="saveCasePlan(\''+sid+'\')">حفظ الخطة</button></div></section>':'';
 const files=secure?'<section class="case-section"><h3>المرفقات السرية</h3><div class="case-files">'+((d.files||[]).map(x=>'<a href="'+esc(x.url||'#')+'" target="_blank" rel="noopener">📎 '+esc(x.title)+'</a>').join('')||'<p>لا توجد ملفات مرفقة.</p>')+'</div><input id="caseFileTitle" placeholder="عنوان الملف"><input id="caseFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx" onchange="useCaseFile(this)"><button onclick="uploadCaseFile(\''+sid+'\')">رفع الملف</button></section>':'';
 S('caseDetail').innerHTML='<section class="student-case-card"><div class="today-title"><div><small>'+esc(s.class_name)+' • رقم '+esc(s.school_id)+'</small><h2>'+esc(s.name)+'</h2></div></div>'+fields+followups+plans+files+'<section class="case-section"><h3>ملاحظات المعلمات</h3><div class="case-notes">'+((d.notes||[]).map(n=>'<article><b>'+esc(n.subject_label||'ملاحظة')+'</b><p>'+esc(n.note)+'</p></article>').join('')||'<p>لا توجد ملاحظات.</p>')+'</div><textarea id="caseNewNote" placeholder="ملاحظتي عن الطالبة"></textarea><button onclick="addCaseNote(\''+sid+'\')">إضافة ملاحظة</button></section><section class="case-section"><h3>المواهب</h3><div>'+d.talents.map(t=>'<span class="talent">'+esc(t.talent_category)+'</span>').join('')+'</div><div class="form-row"><input id="talentCat" placeholder="موهبة الطالبة"><input id="talentDesc" placeholder="وصف الموهبة"></div><button onclick="addTalent(\''+sid+'\')">إضافة موهبة</button></section></section>';S('caseDetail').scrollIntoView({behavior:'smooth'});phCapture('student_case_opened')
 }catch(e){toast(staffError(e))}};
window.saveStudentCase=async sid=>{try{await staffApi('save_student_case',{student_school_id:sid,residence:S('cResidence').value,contact_phone:S('cPhone').value,social_status:S('cSocial').value,living_standard:S('cLiving').value,family_status:S('cFamily').value,health_status:S('cHealth').value,psychological_notes:S('cPsych').value,cognitive_notes:S('cCognitive').value,administrative_notes:S('cAdminNotes').value,support_needs:S('cSupport').value,follow_up_issue:S('cIssue').value,academic_level:S('cLevel').value,follow_up_status:S('cFollowStatus').value,next_follow_up_date:S('cNextDate').value});phCapture('student_case_saved');toast('✅ تم حفظ ملف الطالبة')}catch(e){toast(staffError(e))}};
window.addCaseFollowup=async sid=>{try{await staffApi('add_case_followup',{student_school_id:sid,follow_up_type:S('followType').value,summary:S('followSummary').value,outcome:S('followOutcome').value});phCapture('case_followup_added');toast('✅ تم حفظ المتابعة');openStudentCase(sid)}catch(e){toast(staffError(e))}};
window.saveCasePlan=async sid=>{try{await staffApi('save_case_plan',{student_school_id:sid,title:S('planTitle').value,goals:S('planGoals').value,actions:S('planActions').value,responsible_parties:S('planResponsible').value});phCapture('case_plan_saved');toast('✅ تم حفظ الخطة');openStudentCase(sid)}catch(e){toast(staffError(e))}};
window.useCaseFile=input=>{caseUploadFile=input.files&&input.files[0]||null};
window.uploadCaseFile=async sid=>{if(!caseUploadFile)return toast('اختاري ملفًا أولًا');if(caseUploadFile.size>20*1024*1024)return toast('حجم الملف يجب ألا يتجاوز 20 MB');try{const title=S('caseFileTitle').value.trim()||caseUploadFile.name,u=await staffApi('prepare_case_file_upload',{student_school_id:sid,mime_type:caseUploadFile.type}),up=await fetch(u.signed_url,{method:'PUT',headers:{'Content-Type':caseUploadFile.type,'x-upsert':'false'},body:caseUploadFile});if(!up.ok)throw Object.assign(new Error('upload_failed'),{code:'upload_failed'});await staffApi('complete_case_file_upload',{student_school_id:sid,path:u.path,title,mime_type:caseUploadFile.type,file_size:caseUploadFile.size});phCapture('case_file_uploaded',{mime_type:caseUploadFile.type});toast('📎 تم رفع الملف بسرية');openStudentCase(sid)}catch(e){toast(staffError(e))}};
window.addCaseNote=async sid=>{try{await staffApi('add_case_note',{student_school_id:sid,note:S('caseNewNote').value,subject_label:secureEmployee.profile?.subject||secureEmployee.role,visibility:'all_teachers'});toast('✅ أضيفت الملاحظة');openStudentCase(sid)}catch(e){toast(staffError(e))}};
window.addTalent=async sid=>{try{await staffApi('add_talent',{student_school_id:sid,talent_category:S('talentCat').value,talent_description:S('talentDesc').value});toast('⭐ أضيفت الموهبة');openStudentCase(sid)}catch(e){toast(staffError(e))}};
function renderBuses(){S('staffPane').innerHTML='<h2>🚌 الحافلات والنقلات</h2><div class="bus-list">'+(secureDirectory.buses.length?secureDirectory.buses.map(b=>'<article><em>🚌</em><div><b>'+esc(b.route_name)+'</b><small>'+esc(b.departure_label||'')+' • '+esc(b.destination||'')+'</small><p>السائق: '+esc(b.driver_name||'—')+' • '+esc(b.driver_phone||'—')+'</p></div></article>').join(''):'<div class="staff-empty">لم تُضف بيانات الحافلات بعد.</div>')+'</div>'+(secureAdmin()?'<section class="staff-card"><h3>إضافة نقلة</h3><div class="form-row"><input id="busRoute" placeholder="مثال: مغادرة حافلة النقلة الأولى"><input id="busLabel" placeholder="الهوب عند الوادي (الصفيرية)"></div><div class="form-row"><input id="busDriver" placeholder="اسم السائق"><input id="busPhone" placeholder="رقم الهاتف"></div><button class="staff-primary" onclick="saveBus()">حفظ</button></section>':'')}
window.saveBus=async()=>{try{await staffApi('save_bus',{route_name:S('busRoute').value,departure_label:S('busLabel').value,driver_name:S('busDriver').value,driver_phone:S('busPhone').value});secureDirectory=await staffApi('directory');toast('✅ تم حفظ الحافلة');renderBuses()}catch(e){toast(staffError(e))}};
async function renderAnalytics(){
 const now=new Date(),from=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),to=now.toISOString().slice(0,10),d=await staffApi('analytics',{from,to});const bar=(obj,labels={})=>{const a=Object.entries(obj||{}),max=Math.max(1,...a.map(x=>x[1]));return '<div class="bars">'+a.map(([k,v])=>'<div><span>'+esc(labels[k]||activityNames[k]||k)+'</span><i><b style="width:'+Math.round(v/max*100)+'%"></b></i><strong>'+v+'</strong></div>').join('')+'</div>'};const st={present:'حضور',absent:'غياب',late:'تأخر',excused:'بعذر',permission:'استئذان',partial_permission:'استئذان جزئي',approved:'موافق',pending:'قيد الانتظار',active:'نشط',completed:'مكتمل',organized:'صف منظم',no_teacher:'بلا معلمة',problem:'مشكلة'},rs={health:'صحي',medical_appointment:'موعد طبي',family:'أسري',child:'طفل',government:'جهة حكومية',emergency:'طارئ',official_task:'مهمة رسمية',transport:'مواصلات',other:'أخرى'};S('staffPane').innerHTML='<div class="today-title"><div><small>من '+from+' إلى '+to+'</small><h2>📊 مؤشرات الشهر</h2></div><span class="posthog-chip">PostHog • تحديث دوري</span></div><div class="kpi-grid compact"><div><small>الأنشطة</small><b>'+d.activities.total+'</b></div><div><small>مهام الأنشطة</small><b>'+d.activity_tasks.total+'</b></div><div><small>الموهوبات</small><b>'+d.gifted.total+'</b></div><div><small>متابعات الحالات</small><b>'+d.case_followups.total+'</b></div></div><div class="analytics-grid"><section class="staff-card"><h3>حضور الطالبات</h3>'+bar(d.students.status,st)+'</section><section class="staff-card"><h3>حضور المعلمات</h3>'+bar(d.teachers.status,st)+'</section><section class="staff-card"><h3>أسباب الاستئذان</h3>'+bar(d.permissions.reasons,rs)+'</section><section class="staff-card"><h3>بلاغات الفصول</h3>'+bar(d.observations.status,st)+'</section><section class="staff-card"><h3>الأنشطة حسب النوع</h3>'+bar(d.activities.types)+'</section><section class="staff-card"><h3>حالة مهام الأنشطة</h3>'+bar(d.activity_tasks.status,st)+'</section><section class="staff-card"><h3>مجالات المواهب</h3>'+bar(d.gifted.talents)+'</section><section class="staff-card"><h3>أنواع متابعة الحالات</h3>'+bar(d.case_followups.types)+'</section></div>';phCapture('analytics_viewed',{period:'month'})}
function renderSecurity(){S('staffPane').innerHTML='<div class="two-col"><section class="staff-card"><h2>🔐 إصدار رمز شخصي</h2><p class="staff-help">اختاري الموظفة. يمكن للنظام إنشاء رمز مؤقت، ويُطلب تغييره عند أول دخول.</p><select id="pinEmployee">'+employeeOptions()+'</select><input id="pinCustom" inputmode="numeric" maxlength="12" placeholder="اختياري: اكتبي رمزًا من 6 أرقام"><button class="staff-primary" onclick="issueStaffPin()">إصدار الرمز المؤقت</button><div id="issuedPin"></div></section><section class="staff-card"><h3>حماية الحساب</h3><ul><li>إيقاف مؤقت بعد خمس محاولات خاطئة.</li><li>الجلسة تنتهي تلقائيًا بعد 12 ساعة.</li><li>كل عملية مرتبطة باسم الموظفة وصلاحيتها.</li><li>البيانات الصحية والاجتماعية محجوبة عن غير المخولين.</li></ul></section></div>'}
window.issueStaffPin=async()=>{try{const d=await staffApi('issue_pin',{employee_name:S('pinEmployee').value,pin:S('pinCustom').value});S('issuedPin').innerHTML='<div class="issued-pin"><small>الرمز المؤقت لـ '+esc(d.employee_name)+'</small><b>'+esc(d.temporary_pin)+'</b><p>سلّميه لها بصورة خاصة؛ سيطلب النظام تغييره.</p></div>'}catch(e){toast(staffError(e))}};
setTimeout(async()=>{prepareSecureLogin();injectStaffCenter();updateSecureLabels();await restoreStaff()},0);
